import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// Create axios instance with auth header
const api = axios.create({
  baseURL: "http://localhost:8000",
});

// Add interceptor to include token in requests
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function EmployeeBillUpload() {
  const navigate = useNavigate();
  const [selectedFile, setSelectedFile] = useState(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState(null);
  const [message, setMessage] = useState("");
  const [profile, setProfile] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [myBills, setMyBills] = useState([]);
  const [showBills, setShowBills] = useState(false);
  const [billsLoading, setBillsLoading] = useState(false);
  const [submitMode, setSubmitMode] = useState('auto'); // 'auto' or 'manual'
  const [showSubmitModal, setShowSubmitModal] = useState(false);
  const [billToSubmit, setBillToSubmit] = useState(null);
  const [submitRemarks, setSubmitRemarks] = useState('');

  // Check authentication on component mount
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      navigate("/login");
      return;
    }
    
    fetchProfile();
  }, [navigate]);

  const fetchProfile = async () => {
    try {
      const res = await api.get("/profile");
      setProfile(res.data);
      
      // Check if user is employee
      if (res.data.role !== 'employee') {
        navigate("/team-bills"); // Redirect managers to new manager dashboard
      }
    } catch (err) {
      console.error("Error fetching profile:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      }
    }
  };

  const fetchMyBills = async () => {
    setBillsLoading(true);
    try {
      const res = await api.get("/bills/my-bills?page=1&page_size=10");
      setMyBills(res.data.bills || []);
    } catch (err) {
      console.error("Error fetching bills:", err);
      showMessage("Failed to fetch your bills.", true);
    } finally {
      setBillsLoading(false);
    }
  };

  const showMessage = (msg, isError = false) => {
    setMessage(msg);
    setTimeout(() => setMessage(""), isError ? 7000 : 5000);
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    validateAndSetFile(file);
  };

  const validateAndSetFile = (file) => {
    if (!file) return;

    // Check file type
    const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/bmp', 'image/tiff', 'image/gif', 'application/pdf'];
    if (!allowedTypes.includes(file.type)) {
      showMessage("Please select a valid image file (JPG, PNG, BMP, TIFF, GIF) or PDF.", true);
      return;
    }

    // Check file size (max 10MB)
    const maxSize = 10 * 1024 * 1024; // 10MB
    if (file.size > maxSize) {
      showMessage("File size must be less than 10MB.", true);
      return;
    }

    setSelectedFile(file);
    setResult(null); // Clear previous results
    setMessage("");
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      validateAndSetFile(e.dataTransfer.files[0]);
    }
  };

  const processBill = async () => {
    if (!selectedFile) {
      showMessage("Please select a file first.", true);
      return;
    }

    setIsProcessing(true);
    setMessage("");

    try {
      const formData = new FormData();
      formData.append("file", selectedFile);

      const response = await api.post("/bills/process-bill", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
        timeout: 60000, // 60 second timeout
      });

      const data = response.data;

      if (data.success) {
        setResult(data);
        showMessage(`Bill processed and stored successfully! Bill ID: ${data.bill_id}`);
        // Refresh bills list if it's showing
        if (showBills) {
          fetchMyBills();
        }
      } else {
        showMessage(data.message || "Failed to process the bill.", true);
        setResult(data); // Still show partial results
      }
    } catch (err) {
      console.error("Bill processing error:", err);
      if (err.response?.status === 401) {
        localStorage.removeItem("token");
        navigate("/login");
      } else if (err.code === 'ECONNABORTED') {
        showMessage("Processing timeout. Please try with a smaller file or better quality image.", true);
      } else {
        showMessage(err.response?.data?.detail || "Error processing bill. Please try again.", true);
      }
    } finally {
      setIsProcessing(false);
    }
  };

  const clearResults = () => {
    setSelectedFile(null);
    setResult(null);
    setMessage("");
    // Reset file input
    const fileInput = document.getElementById("file-input");
    if (fileInput) fileInput.value = "";
  };

  const logout = () => {
    localStorage.removeItem("token");
    navigate("/login");
  };

  const goToProfile = () => {
    navigate("/profile");
  };

  const toggleBillsList = () => {
    setShowBills(!showBills);
    if (!showBills) {
      fetchMyBills();
    }
  };

  // Loading spinner component
  const LoadingSpinner = () => (
    <div className="loading-spinner">
      <div className="spinner"></div>
    </div>
  );

  // Get message class based on content
  const getMessageClass = () => {
    if (!message) return "";
    return message.toLowerCase().includes("error") || message.toLowerCase().includes("failed") || message.toLowerCase().includes("timeout")
      ? "message error" 
      : "message success";
  };

  const formatCurrency = (amount, currency = 'USD') => {
    if (amount === null || amount === undefined) return 'N/A';
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency
    }).format(amount);
  };

  const formatDate = (dateStr) => {
    if (!dateStr) return 'N/A';
    try {
      return new Date(dateStr).toLocaleDateString();
    } catch {
      return dateStr;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved': return '#28a745';
      case 'rejected': return '#dc3545';
      case 'under_review': return '#ffc107';
      default: return '#6c757d';
    }
  };

  return (
    <div className="container">
      {/* Header */}
      <div className="bill-header">
        <h1 className="app-title">Employee Bill Upload</h1>
        <div className="user-info-header">
          {profile && (
            <span className="welcome-text">
              Welcome, {profile.full_name || profile.username || profile.email}!
            </span>
          )}
          <div className="header-buttons">
            <button className="btn btn-secondary" onClick={toggleBillsList}>
              {showBills ? 'Hide' : 'Show'} My Bills
            </button>
            <button className="btn btn-secondary" onClick={goToProfile}>
              Profile
            </button>
            <button className="btn btn-danger" onClick={logout}>
              Logout
            </button>
          </div>
        </div>
      </div>

      {/* File Upload Section */}
      <div className="bill-section">
        <h2>Upload Expense Bill</h2>
        <p className="section-description">
          Upload an image or PDF of your expense bill/receipt. The system will automatically extract financial data and store it for manager approval.
        </p>

        {/* Drag and Drop Area */}
        <div
          className={`file-drop-area ${dragActive ? "drag-active" : ""}`}
          onDragEnter={handleDrag}
          onDragLeave={handleDrag}
          onDragOver={handleDrag}
          onDrop={handleDrop}
        >
          <div className="file-drop-content">
            <div className="file-icon">🧾</div>
            <p>Drag and drop your bill here, or</p>
            <label htmlFor="file-input" className="btn btn-primary file-select-btn">
              Choose File
            </label>
            <input
              id="file-input"
              type="file"
              accept=".jpg,.jpeg,.png,.bmp,.tiff,.gif,.pdf"
              onChange={handleFileSelect}
              style={{ display: "none" }}
            />
          </div>
        </div>

        {/* Selected File Info */}
        {selectedFile && (
          <div className="selected-file-info">
            <div className="file-details">
              <strong>Selected File:</strong> {selectedFile.name}
              <br />
              <strong>Size:</strong> {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
              <br />
              <strong>Type:</strong> {selectedFile.type}
            </div>
            <div className="file-actions">
              <button
                className="btn btn-primary"
                onClick={processBill}
                disabled={isProcessing}
              >
                {isProcessing ? (
                  <>
                    <LoadingSpinner />
                    Processing & Storing...
                  </>
                ) : (
                  "Process & Store Bill"
                )}
              </button>
              <button className="btn btn-secondary" onClick={clearResults}>
                Clear
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Processing Result */}
      {result && (
        <div className="bill-section">
          <h2>Processing Result</h2>
          {result.success ? (
            <div className="success-result">
              <h3>✅ Bill Processed Successfully</h3>
              <p><strong>Bill ID:</strong> {result.bill_id}</p>
              <p><strong>Status:</strong> Pending Manager Approval</p>
              {result.bill_data && (
                <div className="bill-summary">
                  <h4>Extracted Information:</h4>
                  <div className="bill-info-grid">
                    <div><strong>Amount:</strong> {formatCurrency(result.bill_data.amount)}</div>
                    <div><strong>Date:</strong> {formatDate(result.bill_data.date)}</div>
                    <div><strong>Vendor:</strong> {result.bill_data.vendor || 'Not detected'}</div>
                    <div><strong>Category:</strong> {result.bill_data.category || 'Miscellaneous'}</div>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="error-result">
              <h3>❌ Processing Failed</h3>
              <p>{result.message}</p>
            </div>
          )}
        </div>
      )}

      {/* My Bills Section */}
      {showBills && (
        <div className="bill-section">
          <h2>My Bills</h2>
          {billsLoading ? (
            <div className="loading-container">
              <LoadingSpinner />
              <p>Loading your bills...</p>
            </div>
          ) : myBills.length > 0 ? (
            <div className="bills-list">
              {myBills.map((bill) => (
                <div key={bill.id} className="bill-item">
                  <div className="bill-header-item">
                    <h4>Bill #{bill.id}</h4>
                    <span 
                      className="status-badge" 
                      style={{ backgroundColor: getStatusColor(bill.status) }}
                    >
                      {bill.status.toUpperCase()}
                    </span>
                  </div>
                  <div className="bill-details-grid">
                    <div><strong>Amount:</strong> {formatCurrency(bill.amount)}</div>
                    <div><strong>Date:</strong> {formatDate(bill.date)}</div>
                    <div><strong>Vendor:</strong> {bill.vendor || 'N/A'}</div>
                    <div><strong>Category:</strong> {bill.category || 'N/A'}</div>
                    <div><strong>Submitted:</strong> {formatDate(bill.created_at)}</div>
                    <div><strong>File:</strong> {bill.filename || 'N/A'}</div>
                  </div>
                  {bill.remarks && (
                    <div className="bill-remarks">
                      <strong>Remarks:</strong> {bill.remarks}
                    </div>
                  )}
                </div>
              ))}
            </div>
          ) : (
            <p>No bills uploaded yet. Upload your first bill above!</p>
          )}
        </div>
      )}

      {/* Processing Overlay */}
      {isProcessing && (
        <div className="processing-overlay">
          <div className="processing-content">
            <LoadingSpinner />
            <h3>Processing your bill...</h3>
            <p>Extracting text, analyzing financial data, and storing to database...</p>
          </div>
        </div>
      )}

      {/* Message Display */}
      {message && <div className={getMessageClass()}>{message}</div>}

      {/* Instructions */}
      <div className="bill-section instructions">
        <h3>Tips for Better Results</h3>
        <div className="tips-grid">
          <div className="tip-item">
            <h4>📸 Image Quality</h4>
            <p>Use high-resolution images with good lighting and contrast</p>
          </div>
          <div className="tip-item">
            <h4>📄 File Format</h4>
            <p>PNG and PDF files often provide better text extraction</p>
          </div>
          <div className="tip-item">
            <h4>🎯 Focus Areas</h4>
            <p>Ensure total amount, date, and vendor name are clearly visible</p>
          </div>
          <div className="tip-item">
            <h4>⏱️ Processing Time</h4>
            <p>Bills are stored immediately and sent to your manager for approval</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default EmployeeBillUpload;
